//! Slice 2a mechanisms: async memos over host flights, pending and error
//! status, `refresh`, the untracked `latest`/`isPending` windows, staged
//! errors, linked lanes and the pass-scoped transaction.
//!
//! The op programs and their traces are in fixtures/slice2a-units.json; the
//! traces are Solid's (rc.21, regenerated by
//! docs/slice2a-fuzz/tools/unit-expectations.mjs from unit-programs.json).
use rust_solid::slice1::{Out, Runtime, Thrown};
use serde_json::Value;
use std::{
    io::Write,
    process::{Command, Stdio},
    rc::Rc,
};

fn driver(ops: &Value) -> Value {
    let mut child = Command::new(env!("CARGO_BIN_EXE_slice1-driver"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    writeln!(child.stdin.take().unwrap(), "{ops}").unwrap();
    let out = child.wait_with_output().unwrap();
    serde_json::from_slice(&out.stdout).unwrap()
}

fn unit(name: &str) {
    let all: Value = serde_json::from_str(include_str!("fixtures/slice2a-units.json")).unwrap();
    let case = &all[name];
    assert_eq!(driver(&case["ops"]), case["expected"], "{name}");
}

