/// `createMemo(() => flight('q:' + s()).promise)` under a root (an owned
/// memo, as fuzz/solid.mjs creates them).
fn flight_memo(r: &mut Runtime) -> (usize, usize) {
    let root = r.create_root();
    r.with_owner(Some(root), |r| {
        let s = r.signal(1);
        let a = r.memo_async(
            Rc::new(move |r, _| Ok(Out::Flight(format!("q:{}", r.read(s).unwrap())))),
            None,
        );
        (s, a)
    })
}

// The expected values of the two tests below are Solid's (checked with the
// same calls on dist/prod).
#[test]
fn an_uninitialized_flight_is_loading_not_pending() {
    let mut r = Runtime::default();
    let (_, a) = flight_memo(&mut r);
    assert!(matches!(
        &*r.read_value(a).unwrap_err(),
        Thrown::NotReady(_)
    ));
    assert!(r.latest(a).unwrap_err().is_not_ready());
    assert!(!r.is_pending(a).unwrap());
    r.settle_flight("q:1", Ok(5));
    r.run_microtasks(&mut |_, _| {});
    r.flush();
    assert_eq!(r.read(a).unwrap(), 5);
    // A promise settles once: a second settlement changes nothing.
    r.settle_flight("q:1", Ok(6));
    r.run_microtasks(&mut |_, _| {});
    r.flush();
    assert_eq!(r.read(a).unwrap(), 5);
}

#[test]
fn a_refetch_keeps_the_committed_value_and_is_pending() {
    let mut r = Runtime::default();
    let (s, a) = flight_memo(&mut r);
    r.settle_flight("q:1", Ok(5));
    r.run_microtasks(&mut |_, _| {});
    r.write(s, 2);
    r.flush();
    assert_eq!(r.read(a).unwrap(), 5);
    assert_eq!(r.latest(a).unwrap(), Some(5));
    assert!(r.is_pending(a).unwrap());
    r.settle_flight("q:2", Err("nope".into()));
    r.run_microtasks(&mut |_, _| {});
    r.flush();
    let e = r.read_value(a).unwrap_err();
    assert_eq!(e.message(), "nope");
    assert!(matches!(&*e, Thrown::Status { .. }));
    assert!(!r.is_pending(a).unwrap());
}
